import { z } from 'zod';
import { DomainEvent } from '@agentic-ddd/core';
import { AgentEvent } from '@agentic-ddd/decorators';

@AgentEvent({ description: 'Uma tarefa foi criada.', payload: z.object({ taskId: z.string(), title: z.string() }) })
export class TaskCreated extends DomainEvent<{ readonly taskId: string; readonly title: string }> {}

@AgentEvent({ description: 'Uma tarefa foi concluída.', payload: z.object({ taskId: z.string() }) })
export class TaskCompleted extends DomainEvent<{ readonly taskId: string }> {}

import type { Repository } from '@agentic-ddd/core';
import type { Task } from './task';
export type TaskRepository = Repository<Task, string>;

import { AggregateRoot, DomainError, notImplemented } from '@agentic-ddd/core';
import { AgentEntity, AgentMethod, Invariant } from '@agentic-ddd/decorators';
import { TaskCreated, TaskCompleted } from './task.events';

@AgentEntity({ description: 'Tarefa com título e ciclo de vida pendente ou concluído.', states: ['pending', 'completed'] })
@Invariant({ id: 'titulo-obrigatorio', text: 'Toda tarefa precisa de título não vazio.' })
export class Task extends AggregateRoot<string> {
  #status: 'pending' | 'completed' = 'pending';
  private constructor(id: string, readonly title: string) { super(id); }
  get status(): 'pending' | 'completed' { return this.#status; }

  @AgentMethod({ description: 'Cria uma tarefa pendente e remove espaços nas extremidades do título.', emits: [TaskCreated] })
  static create(id: string, title: string): Task {
    return notImplemented();













  }

  @AgentMethod({ description: 'Conclui uma tarefa pendente; repetição falha com TASK_ALREADY_COMPLETED.', transition: { from: ['pending'], to: 'completed' }, emits: [TaskCompleted] })
  complete(): void {
    return notImplemented();













  }
}

import type { TaskRepository } from '../domain/task.repository';
import type { Task } from '../domain/task';

export class InMemoryTaskRepository implements TaskRepository {
  readonly #tasks = new Map<string, Task>();
  async findById(id: string): Promise<Task | null> { return this.#tasks.get(id) ?? null; }
  async save(task: Task): Promise<void> { this.#tasks.set(task.id, task); }
}

import { Operator } from '@agentic-ddd/decorators';
import { CreateTask } from '../application/create-task';
import { CompleteTask } from '../application/complete-task';

@Operator({ name: 'task-operator', description: 'Cria e conclui tarefas conforme pedido do usuário.', instructions: 'Use as tools para criar e concluir tarefas. Identifique a tarefa pelo id e responda em português.', useCases: [CreateTask, CompleteTask] })
export class TaskOperator {}

